int fd = 5;
off_t offset = 0;
off_t len = 4096 * 10;

// Advise kernel to pre-fetch the next N bytes
int advice_will = POSIX_FADV_WILLNEED;
int ret1 = posix_fadvise(fd, offset, len, advice_will);

// Advise kernel data will not be needed soon (discard cache)
int advice_dont = POSIX_FADV_DONTNEED;
int ret2 = posix_fadvise(fd, 0, 0, advice_dont); // len=0 means until EOF

// Set access pattern to mostly random
posix_fadvise(fd, 0, len, POSIX_FADV_RANDOM);
